DECLARE
    v_quotation_id INT := p_quotation_id;
    v_item RECORD;
    v_tax RECORD;
    v_pax RECORD;
    v_var RECORD;
    v_combo RECORD;
    v_quotation_product_id INT;
BEGIN
    -- 1. Check existence
    IF NOT EXISTS (SELECT 1 FROM public."Quotation" WHERE id = v_quotation_id) THEN
        p_mensaje_resultado := 'ERROR: Cotización no encontrada con ID ' || v_quotation_id;
        RETURN;
    END IF;

    -- 2. Update Header
    UPDATE public."Quotation" SET
        "clientId" = (p_data->>'clientId')::INT,
        "currency" = p_data->>'currency',
        "exchangeRate" = (p_data->>'exchangeRate')::FLOAT,
        "branchId" = (p_data->>'branchId')::INT,
        "implantId" = (p_data->>'implantId')::INT,
        "sellerId" = (p_data->>'sellerId')::INT,
        "ticketPrinterId" = (p_data->>'ticketPrinterId')::INT,
        "commissionPercentage" = (p_data->>'commissionPercentage')::FLOAT,
        "chargesAndTaxes" = (p_data->>'chargesAndTaxes')::FLOAT,
        "totalAmount" = (p_data->>'totalAmount')::FLOAT,
        "userId" = p_acting_user_id
    WHERE id = v_quotation_id;

    -- 3. Delete related sub-tables (simulating the Prisma pattern used in PUT)
    -- Cascade will handle many, but for clear SP process we ensure.
    DELETE FROM public."QuotationCombo" WHERE "quotationId" = v_quotation_id;
    DELETE FROM public."QuotationProduct" WHERE "quotationId" = v_quotation_id;

    -- 4. Re-create Combos
    IF p_data ? 'combos' THEN
        FOR v_combo IN SELECT * FROM jsonb_to_recordset(p_data->'combos') AS x("comboId" INT, "id" INT)
        LOOP
            INSERT INTO public."QuotationCombo" ("quotationId", "comboId")
            VALUES (v_quotation_id, COALESCE(v_combo."comboId", v_combo."id"));
        END LOOP;
    END IF;

    -- 5. Re-create Products
    IF p_data ? 'items' THEN
        FOR v_item IN SELECT * FROM jsonb_to_recordset(p_data->'items') AS x(
            "productId" INT, quantity INT, price FLOAT, "providerId" INT, "hotelId" INT,
            "checkIn" TEXT, "checkOut" TEXT, "nights" INT, "mainTaxId" INT,
            "paxAdults" INT, "paxChildren" INT, "serviceType" TEXT, "destination" TEXT,
            "reservationCode" TEXT, "sellerCommission" FLOAT, "ticketPrinterCommission" FLOAT,
            "comboId" INT, "appliedTaxes" JSONB, "passengers" JSONB, "variables" JSONB
        )
        LOOP
            INSERT INTO public."QuotationProduct" (
                "quotationId", "productId", "quantity", "price", "providerId", "hotelId",
                "checkInDate", "checkOutDate", "nights", "paxAdults", "paxChildren",
                "serviceType", "destination", "reservationCode", "sellerCommission", 
                "ticketPrinterCommission", "comboId", "mainTaxId"
            ) VALUES (
                v_quotation_id, v_item."productId", v_item.quantity, v_item.price, v_item."providerId", v_item."hotelId",
                CASE WHEN v_item."checkIn" <> '' THEN v_item."checkIn"::TIMESTAMP ELSE NULL END,
                CASE WHEN v_item."checkOut" <> '' THEN v_item."checkOut"::TIMESTAMP ELSE NULL END,
                COALESCE(v_item.nights, 0), v_item."paxAdults", v_item."paxChildren",
                v_item."serviceType", v_item."destination", v_item."reservationCode", v_item."sellerCommission",
                v_item."ticketPrinterCommission", v_item."comboId", v_item."mainTaxId"
            ) RETURNING id INTO v_quotation_product_id;

            -- 5.1. Handle Passengers
            IF v_item.passengers IS NOT NULL THEN
                FOR v_pax IN SELECT * FROM jsonb_to_recordset(v_item.passengers) AS x(name TEXT, document TEXT)
                LOOP
                    INSERT INTO public."QuotationProductPassenger" ("quotationProductId", "name", "document")
                    VALUES (v_quotation_product_id, v_pax.name, v_pax.document);
                END LOOP;
            END IF;

            -- 5.2. Handle Taxes
            IF v_item."appliedTaxes" IS NOT NULL THEN
                FOR v_tax IN SELECT * FROM jsonb_to_recordset(v_item."appliedTaxes") AS x(id INT, amount FLOAT)
                LOOP
                    INSERT INTO public."QuotationProductTax" (
                        "quotationProductId", "chargeAndTaxId", "valueSnapshot", "valueTypeSnapshot", "explicitAmount", "isMain"
                    )
                    SELECT v_quotation_product_id, ct.id, ct.value, ct.valueType, v_tax.amount, 
                           CASE WHEN v_item."mainTaxId" = ct.id THEN TRUE ELSE FALSE END
                    FROM public."ChargeAndTax" ct
                    WHERE ct.id = v_tax.id;
                END LOOP;
            END IF;

            -- 5.3. Handle Variables
            IF v_item.variables IS NOT NULL THEN
                FOR v_var IN SELECT * FROM jsonb_to_recordset(v_item.variables) AS x("masterVariableId" INT, value TEXT)
                LOOP
                    INSERT INTO public."QuotationProductVariable" ("quotationProductId", "masterVariableId", "value")
                    VALUES (v_quotation_product_id, v_var."masterVariableId", v_var.value);
                END LOOP;
            END IF;
        END LOOP;
    END IF;

    p_mensaje_resultado := 'SUCCESS: Cotización ' || v_quotation_id || ' actualizada con éxito.';

EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
        ROLLBACK;
END;

DECLARE
    v_internal_number TEXT;
    v_quotation_id INT;
    v_item RECORD;
    v_tax RECORD;
    v_pax RECORD;
    v_var RECORD;
    v_combo RECORD;
    v_quotation_product_id INT;
BEGIN
    -- 1. Generate internal number
    v_internal_number := 'QUO-' || to_char(CURRENT_DATE, 'YYYYMMDD') || '-' || floor(random() * 1000)::text;

    -- 2. Create Quotation Header
    INSERT INTO public."Quotation" (
        "internalNumber", "date", "clientId", "currency", "exchangeRate", 
        "branchId", "implantId", "sellerId", "ticketPrinterId", 
        "baseCommissionable", "commissionPercentage", "chargesAndTaxes", 
        "totalAmount", "userId"
    ) VALUES (
        v_internal_number, CURRENT_TIMESTAMP, (p_data->>'clientId')::INT, p_data->>'currency', (p_data->>'exchangeRate')::FLOAT,
        (p_data->>'branchId')::INT, (p_data->>'implantId')::INT, (p_data->>'sellerId')::INT, (p_data->>'ticketPrinterId')::INT,
        0, (p_data->>'commissionPercentage')::FLOAT, (p_data->>'chargesAndTaxes')::FLOAT,
        (p_data->>'totalAmount')::FLOAT, p_acting_user_id
    ) RETURNING id INTO v_quotation_id;

    -- 3. Handle Combos
    FOR v_combo IN SELECT * FROM jsonb_to_recordset(p_data->'combos') AS x(comboId INT)
    LOOP
        INSERT INTO public."QuotationCombo" ("quotationId", "comboId")
        VALUES (v_quotation_id, v_combo.comboId);
    END LOOP;

    -- 4. Handle Products
    FOR v_item IN SELECT *, (ordinality - 1) as idx 
                  FROM jsonb_to_recordset(p_data->'items') WITH ORDINALITY AS x(
                      "productId" INT, quantity INT, price FLOAT, "providerId" INT, "hotelId" INT,
                      "checkIn" TEXT, "checkOut" TEXT, "nights" INT, "mainTaxId" INT,
                      "paxAdults" INT, "paxChildren" INT, "serviceType" TEXT, "destination" TEXT,
                      "reservationCode" TEXT, "sellerCommission" FLOAT, "ticketPrinterCommission" FLOAT,
                      "comboId" INT, "appliedTaxes" JSONB, "passengers" JSONB, "variables" JSONB
                  )
    LOOP
        INSERT INTO public."QuotationProduct" (
            "quotationId", "productId", "quantity", "price", "providerId", "hotelId",
            "checkInDate", "checkOutDate", "nights", "paxAdults", "paxChildren",
            "serviceType", "destination", "reservationCode", "sellerCommission", 
            "ticketPrinterCommission", "comboId", "mainTaxId"
        ) VALUES (
            v_quotation_id, v_item."productId", v_item.quantity, v_item.price, v_item."providerId", v_item."hotelId",
            CASE WHEN v_item."checkIn" <> '' THEN v_item."checkIn"::TIMESTAMP ELSE NULL END,
            CASE WHEN v_item."checkOut" <> '' THEN v_item."checkOut"::TIMESTAMP ELSE NULL END,
            v_item.nights, v_item."paxAdults", v_item."paxChildren",
            v_item."serviceType", v_item."destination", v_item."reservationCode", v_item."sellerCommission",
            v_item."ticketPrinterCommission", v_item."comboId", v_item."mainTaxId"
        ) RETURNING id INTO v_quotation_product_id;

        -- 4.1. Handle Passengers
        FOR v_pax IN SELECT * FROM jsonb_to_recordset(v_item.passengers) AS x(name TEXT, document TEXT)
        LOOP
            INSERT INTO public."QuotationProductPassenger" ("quotationProductId", "name", "document")
            VALUES (v_quotation_product_id, v_pax.name, v_pax.document);
        END LOOP;

        -- 4.2. Handle Taxes
        FOR v_tax IN SELECT * FROM jsonb_to_recordset(v_item."appliedTaxes") AS x(id INT, amount FLOAT)
        LOOP
            -- Get static data from ChargeAndTax for snapshot
            INSERT INTO public."QuotationProductTax" (
                "quotationProductId", "chargeAndTaxId", "valueSnapshot", "valueTypeSnapshot", "explicitAmount", "isMain"
            )
            SELECT v_quotation_product_id, ct.id, ct.value, ct.valueType, v_tax.amount, 
                   CASE WHEN v_item."mainTaxId" = ct.id THEN TRUE ELSE FALSE END
            FROM public."ChargeAndTax" ct
            WHERE ct.id = v_tax.id;
        END LOOP;

        -- 4.3. Handle Variables
        FOR v_var IN SELECT * FROM jsonb_to_recordset(v_item.variables) AS x("masterVariableId" INT, value TEXT)
        LOOP
            INSERT INTO public."QuotationProductVariable" ("quotationProductId", "masterVariableId", "value")
            VALUES (v_quotation_product_id, v_var."masterVariableId", v_var.value);
        END LOOP;
    END LOOP;

    p_quotation_id := v_quotation_id;
    p_mensaje_resultado := 'SUCCESS: Cotización creada correctamente con ID ' || v_quotation_id;

EXCEPTION
    WHEN OTHERS THEN
        p_mensaje_resultado := 'ERROR: ' || SQLERRM;
        ROLLBACK;
END;

