DECLARE
    v_item RECORD;
    v_count INT := 0;
    v_errors TEXT := '';
    v_branch_id INT;
    v_provider_id INT;
    v_role_id INT;
    v_hashed_password TEXT := '$2a$10$7zB.Y7S5y5y5y5y5y5y5y.y5y5y5y5y5y5y5y5y5y5y5y5y5y5y'; -- Placeholder hash
BEGIN
    FOR v_item IN SELECT * FROM jsonb_to_recordset(p_data) AS x
    LOOP
        BEGIN
            IF p_tipo = 'sucursales' THEN
                IF v_item.code IS NOT NULL AND v_item.name IS NOT NULL THEN
                    INSERT INTO public."Branch" ("code", "name")
                    VALUES (v_item.code, v_item.name)
                    ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name";
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'implants' THEN
                IF v_item.code IS NOT NULL AND v_item.name IS NOT NULL THEN
                    v_branch_id := NULL;
                    IF v_item."branchCode" IS NOT NULL THEN
                        SELECT id INTO v_branch_id FROM public."Branch" WHERE "code" = v_item."branchCode";
                    END IF;

                    INSERT INTO public."Implant" ("code", "name", "branchId")
                    VALUES (v_item.code, v_item.name, v_branch_id)
                    ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name", "branchId" = EXCLUDED."branchId";
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'vendedores' THEN
                IF v_item.name IS NOT NULL THEN
                    IF v_item.code IS NOT NULL THEN
                        INSERT INTO public."Seller" ("code", "name", "email")
                        VALUES (v_item.code, v_item.name, v_item.email)
                        ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name", "email" = EXCLUDED."email";
                    ELSE
                        INSERT INTO public."Seller" ("name", "email") VALUES (v_item.name, v_item.email);
                    END IF;
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'tiqueteadores' THEN
                IF v_item.name IS NOT NULL THEN
                    IF v_item.code IS NOT NULL THEN
                        INSERT INTO public."TicketPrinter" ("code", "name", "email")
                        VALUES (v_item.code, v_item.name, v_item.email)
                        ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name", "email" = EXCLUDED."email";
                    ELSE
                        INSERT INTO public."TicketPrinter" ("name", "email") VALUES (v_item.name, v_item.email);
                    END IF;
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'impuestos' THEN
                IF v_item.name IS NOT NULL AND v_item.type IS NOT NULL THEN
                    INSERT INTO public."ChargeAndTax" ("name", "type", "valueType", "value", "isEditable")
                    VALUES (v_item.name, v_item.type, v_item."valueType", (v_item.value)::DECIMAL, TRUE);
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'clientes' THEN
                IF v_item.document IS NOT NULL AND v_item.name IS NOT NULL THEN
                    INSERT INTO public."Client" ("document", "name", "contactInfo", "address")
                    VALUES (v_item.document, v_item.name, v_item."contactInfo", v_item.address)
                    ON CONFLICT ("document") DO UPDATE SET 
                        "name" = EXCLUDED."name", 
                        "contactInfo" = EXCLUDED."contactInfo", 
                        "address" = EXCLUDED."address";
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'proveedores' THEN
                IF v_item.name IS NOT NULL THEN
                    IF v_item.code IS NOT NULL THEN
                        INSERT INTO public."Provider" ("code", "name", "contactInfo")
                        VALUES (v_item.code, v_item.name, v_item."contactInfo")
                        ON CONFLICT ("code") DO UPDATE SET 
                            "name" = EXCLUDED."name", 
                            "contactInfo" = EXCLUDED."contactInfo";
                    ELSE
                        INSERT INTO public."Provider" ("name", "contactInfo") VALUES (v_item.name, v_item."contactInfo");
                    END IF;
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'productos' THEN
                IF v_item.description IS NOT NULL THEN
                    IF v_item.code IS NOT NULL THEN
                        INSERT INTO public."Product" ("code", "type", "description", "basePrice", "billingConcept", "serviceType")
                        VALUES (v_item.code, COALESCE(v_item.type, 'SERVICE'), v_item.description, (v_item."basePrice")::DECIMAL, v_item."billingConcept", v_item."serviceType")
                        ON CONFLICT ("code") DO UPDATE SET 
                            "type" = EXCLUDED."type",
                            "description" = EXCLUDED."description",
                            "basePrice" = EXCLUDED."basePrice",
                            "billingConcept" = EXCLUDED."billingConcept",
                            "serviceType" = EXCLUDED."serviceType";
                    ELSE
                        INSERT INTO public."Product" ("type", "description", "basePrice", "billingConcept", "serviceType")
                        VALUES (COALESCE(v_item.type, 'SERVICE'), v_item.description, (v_item."basePrice")::DECIMAL, v_item."billingConcept", v_item."serviceType");
                    END IF;
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'hoteles' THEN
                IF v_item.name IS NOT NULL AND v_item."providerName" IS NOT NULL THEN
                    SELECT id INTO v_provider_id FROM public."Provider" WHERE "name" ILIKE '%' || v_item."providerName" || '%' LIMIT 1;
                    IF v_provider_id IS NOT NULL THEN
                        IF v_item.code IS NOT NULL THEN
                            INSERT INTO public."Hotel" ("code", "name", "category", "location", "providerId")
                            VALUES (v_item.code, v_item.name, COALESCE(v_item.category, v_item.stars, '3*'), v_item.location, v_provider_id)
                            ON CONFLICT ("code") DO UPDATE SET 
                                "name" = EXCLUDED."name",
                                "category" = EXCLUDED."category",
                                "location" = EXCLUDED."location",
                                "providerId" = EXCLUDED."providerId";
                        ELSE
                            INSERT INTO public."Hotel" ("name", "category", "location", "providerId")
                            VALUES (v_item.name, COALESCE(v_item.category, v_item.stars, '3*'), v_item.location, v_provider_id);
                        END IF;
                        v_count := v_count + 1;
                    END IF;
                END IF;

            ELSIF p_tipo = 'usuarios' THEN
                IF v_item.email IS NOT NULL AND v_item.name IS NOT NULL THEN
                    SELECT id INTO v_role_id FROM public."Role" WHERE "name" ILIKE '%' || COALESCE(v_item."roleName", 'Seller') || '%' LIMIT 1;
                    IF v_role_id IS NOT NULL THEN
                        INSERT INTO public."User" ("email", "name", "roleId", "passwordHash")
                        VALUES (v_item.email, v_item.name, v_role_id, v_hashed_password)
                        ON CONFLICT ("email") DO UPDATE SET 
                            "name" = EXCLUDED."name",
                            "roleId" = EXCLUDED."roleId";
                        v_count := v_count + 1;
                    END IF;
                END IF;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || 'Error en item: ' || SQLERRM || '; ';
        END;
    END LOOP;

    p_mensaje_resultado := 'SUCCESS: Procesados ' || v_count || ' registros. ' || CASE WHEN v_errors <> '' THEN 'Errores: ' || v_errors ELSE '' END;
END;

DECLARE
    v_row_text TEXT;
    v_cols TEXT[];
    v_count INT := 0;
    v_errors TEXT := '';
    v_branch_id INT;
    v_provider_id INT;
    v_role_id INT;
    v_hashed_password TEXT := '$2a$10$7zB.Y7S5y5y5y5y5y5y5y.y5y5y5y5y5y5y5y5y5y5y5y5y5y5y'; -- Placeholder hash
BEGIN
    FOR v_row_text IN SELECT unnest(string_to_array(p_text_data, E'\n')) LOOP
        IF TRIM(v_row_text) = '' THEN CONTINUE; END IF;

        BEGIN
            v_cols := string_to_array(v_row_text, '^');

            IF p_tipo = 'sucursales' THEN
                -- Format: code^name
                IF v_cols[1] IS NOT NULL AND v_cols[2] IS NOT NULL THEN
                    INSERT INTO public."Branch" ("code", "name")
                    VALUES (TRIM(v_cols[1]), TRIM(v_cols[2]))
                    ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name";
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'implants' THEN
                -- Format: code^name^branchCode
                IF v_cols[1] IS NOT NULL AND v_cols[2] IS NOT NULL THEN
                    v_branch_id := NULL;
                    IF v_cols[3] IS NOT NULL AND TRIM(v_cols[3]) <> '' THEN
                        SELECT id INTO v_branch_id FROM public."Branch" WHERE LOWER("code") = LOWER(TRIM(v_cols[3]));
                    END IF;

                    INSERT INTO public."Implant" ("code", "name", "branchId")
                    VALUES (TRIM(v_cols[1]), TRIM(v_cols[2]), v_branch_id)
                    ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name", "branchId" = EXCLUDED."branchId";
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'vendedores' THEN
                -- Format: name^email^code
                IF v_cols[1] IS NOT NULL THEN
                    IF v_cols[3] IS NOT NULL AND TRIM(v_cols[3]) <> '' THEN
                        INSERT INTO public."Seller" ("code", "name", "email")
                        VALUES (TRIM(v_cols[3]), TRIM(v_cols[1]), NULLIF(TRIM(v_cols[2]), ''))
                        ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name", "email" = EXCLUDED."email";
                    ELSE
                        INSERT INTO public."Seller" ("name", "email") VALUES (TRIM(v_cols[1]), NULLIF(TRIM(v_cols[2]), ''));
                    END IF;
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'tiqueteadores' THEN
                -- Format: name^email^code
                IF v_cols[1] IS NOT NULL THEN
                    IF v_cols[3] IS NOT NULL AND TRIM(v_cols[3]) <> '' THEN
                        INSERT INTO public."TicketPrinter" ("code", "name", "email")
                        VALUES (TRIM(v_cols[3]), TRIM(v_cols[1]), NULLIF(TRIM(v_cols[2]), ''))
                        ON CONFLICT ("code") DO UPDATE SET "name" = EXCLUDED."name", "email" = EXCLUDED."email";
                    ELSE
                        INSERT INTO public."TicketPrinter" ("name", "email") VALUES (TRIM(v_cols[1]), NULLIF(TRIM(v_cols[2]), ''));
                    END IF;
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'impuestos' THEN
                -- Format: code^name^type^valueType^value
                IF v_cols[2] IS NOT NULL AND v_cols[3] IS NOT NULL THEN
                    INSERT INTO public."ChargeAndTax" ("code", "name", "type", "valueType", "value", "isEditable", "inNationality")
                    VALUES (TRIM(v_cols[1]), TRIM(v_cols[2]), TRIM(v_cols[3]), TRIM(v_cols[4]), NULLIF(TRIM(v_cols[5]), '')::DECIMAL, TRUE, COALESCE(NULLIF(TRIM(v_cols[6]), '')::INT, 1))
                    ON CONFLICT ("code") DO UPDATE SET 
                        "name" = EXCLUDED."name",
                        "type" = EXCLUDED."type",
                        "valueType" = EXCLUDED."valueType",
                        "value" = EXCLUDED."value",
                        "inNationality" = EXCLUDED."inNationality";
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'clientes' THEN
                -- Format: document^name^contactInfo^address
                IF v_cols[1] IS NOT NULL AND v_cols[2] IS NOT NULL THEN
                    INSERT INTO public."Client" ("document", "name", "contactInfo", "address")
                    VALUES (TRIM(v_cols[1]), TRIM(v_cols[2]), TRIM(v_cols[3]), TRIM(v_cols[4]))
                    ON CONFLICT ("document") DO UPDATE SET 
                        "name" = EXCLUDED."name", 
                        "contactInfo" = EXCLUDED."contactInfo", 
                        "address" = EXCLUDED."address";
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'proveedores' THEN
                -- Format: name^contactInfo^code
                IF v_cols[1] IS NOT NULL THEN
                    IF v_cols[3] IS NOT NULL AND TRIM(v_cols[3]) <> '' THEN
                        INSERT INTO public."Provider" ("code", "name", "contactInfo")
                        VALUES (TRIM(v_cols[3]), TRIM(v_cols[1]), NULLIF(TRIM(v_cols[2]), ''))
                        ON CONFLICT ("code") DO UPDATE SET 
                            "name" = EXCLUDED."name", 
                            "contactInfo" = EXCLUDED."contactInfo";
                    ELSE
                        INSERT INTO public."Provider" ("name", "contactInfo") VALUES (TRIM(v_cols[1]), NULLIF(TRIM(v_cols[2]), ''));
                    END IF;
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'productos' THEN
                -- Format: description^basePrice^code^type^billingConcept^serviceType
                IF v_cols[1] IS NOT NULL THEN
                    IF v_cols[3] IS NOT NULL AND TRIM(v_cols[3]) <> '' THEN
                        INSERT INTO public."Product" ("code", "type", "description", "basePrice", "billingConcept", "serviceType")
                        VALUES (TRIM(v_cols[3]), COALESCE(TRIM(v_cols[4]), 'SERVICE'), TRIM(v_cols[1]), NULLIF(TRIM(v_cols[2]), '')::DECIMAL, TRIM(v_cols[5]), TRIM(v_cols[6]))
                        ON CONFLICT ("code") DO UPDATE SET 
                            "type" = EXCLUDED."type",
                            "description" = EXCLUDED."description",
                            "basePrice" = EXCLUDED."basePrice",
                            "billingConcept" = EXCLUDED."billingConcept",
                            "serviceType" = EXCLUDED."serviceType";
                    ELSE
                        INSERT INTO public."Product" ("type", "description", "basePrice", "billingConcept", "serviceType")
                        VALUES (COALESCE(TRIM(v_cols[4]), 'SERVICE'), TRIM(v_cols[1]), NULLIF(TRIM(v_cols[2]), '')::DECIMAL, TRIM(v_cols[5]), TRIM(v_cols[6]));
                    END IF;
                    v_count := v_count + 1;
                END IF;

            ELSIF p_tipo = 'hoteles' THEN
                -- Format: name^providerNM^code^category^location
                IF v_cols[1] IS NOT NULL AND v_cols[2] IS NOT NULL THEN
                    SELECT id INTO v_provider_id FROM public."Provider" WHERE "name" ILIKE '%' || TRIM(v_cols[2]) || '%' LIMIT 1;
                    IF v_provider_id IS NOT NULL THEN
                        IF v_cols[3] IS NOT NULL AND TRIM(v_cols[3]) <> '' THEN
                            INSERT INTO public."Hotel" ("code", "name", "category", "location", "providerId")
                            VALUES (TRIM(v_cols[3]), TRIM(v_cols[1]), COALESCE(TRIM(v_cols[4]), '3*'), TRIM(v_cols[5]), v_provider_id)
                            ON CONFLICT ("code") DO UPDATE SET 
                                "name" = EXCLUDED."name",
                                "category" = EXCLUDED."category",
                                "location" = EXCLUDED."location",
                                "providerId" = EXCLUDED."providerId";
                        ELSE
                            INSERT INTO public."Hotel" ("name", "category", "location", "providerId")
                            VALUES (TRIM(v_cols[1]), COALESCE(TRIM(v_cols[4]), '3*'), TRIM(v_cols[5]), v_provider_id);
                        END IF;
                        v_count := v_count + 1;
                    END IF;
                END IF;

            ELSIF p_tipo = 'usuarios' THEN
                -- Format: email^name^roleName^password
                IF v_cols[1] IS NOT NULL AND v_cols[2] IS NOT NULL THEN
                    SELECT id INTO v_role_id FROM public."Role" WHERE "name" ILIKE '%' || COALESCE(TRIM(v_cols[3]), 'Seller') || '%' LIMIT 1;
                    IF v_role_id IS NOT NULL THEN
                        INSERT INTO public."User" ("email", "name", "roleId", "passwordHash")
                        VALUES (TRIM(v_cols[1]), TRIM(v_cols[2]), v_role_id, v_hashed_password)
                        ON CONFLICT ("email") DO UPDATE SET 
                            "name" = EXCLUDED."name",
                            "roleId" = EXCLUDED."roleId";
                        v_count := v_count + 1;
                    END IF;
                END IF;
            END IF;
        EXCEPTION WHEN OTHERS THEN
            v_errors := v_errors || 'Error en item: ' || SQLERRM || '; ';
        END;
    END LOOP;

    p_mensaje_resultado := 'SUCCESS: Procesados ' || v_count || ' registros. ' || CASE WHEN v_errors <> '' THEN 'Errores: ' || v_errors ELSE '' END;
END;
